fn at(p: f64, t: f64) -> anyhow::Result<steam::SteamProperties> {
    steam::properties(
        Pressure::new::<pascal>(p),
        ThermodynamicTemperature::new::<kelvin>(t),
    )
    .with_context(|| format!("{p} Pa, {t} K"))
}

/// [v, h, u, s, cp, cv, w] in SI.
fn si(x: &steam::SteamProperties) -> [f64; 7] {
    [
        x.specific_volume.get::<cubic_meter_per_kilogram>(),
        x.enthalpy.get::<joule_per_kilogram>(),
        x.internal_energy.get::<joule_per_kilogram>(),
        x.entropy.get::<joule_per_kilogram_kelvin>(),
        x.cp.get::<joule_per_kilogram_kelvin>(),
        x.cv.get::<joule_per_kilogram_kelvin>(),
        x.speed_of_sound.get::<meter_per_second>(),
    ]
}

const NAMES: [&str; 7] = ["v", "h", "u", "s", "cp", "cv", "w"];

#[test]
fn test_steam_properties_match_coolprop_if97() -> anyhow::Result<()> {
    for row in GOLDEN {
        let (p, t) = (row[0], row[1]);
        let got = si(&at(p, t)?);
        for ((name, got), want) in NAMES.iter().zip(got).zip(&row[2..]) {
            // Absolute floor for u and s, which pass through zero near the
            // triple point.
            let error = (got - want).abs() / want.abs().max(1e3);
            anyhow::ensure!(
                error < 1e-10,
                "{name} at {p} Pa, {t} K: {got} vs {want} ({error:e})"
            );
        }
    }
    Ok(())
}

#[test]
fn test_steam_regions_2_and_5_agree_at_1073_k() -> anyhow::Result<()> {
    // IF97's own inconsistency between the two regions (measured with
    // CoolProp): v ~1e-4, h and s ~2e-5, cp ~7e-4.
    let tolerance = [2e-4, 5e-5, 5e-5, 5e-5, 1e-3, 1e-3, 1e-3];
    for p in [1e4, 1e6, 1e7, 5e7] {
        let below = at(p, 1073.15)?;
        let above = at(p, 1073.15 + 1e-9)?;
        anyhow::ensure!(
            below.region == Region::Vapour && above.region == Region::HighTemperature,
            "{:?} / {:?}",
            below.region,
            above.region
        );
        for (((name, a), b), tol) in NAMES.iter().zip(si(&below)).zip(si(&above)).zip(tolerance) {
            let jump = (a / b - 1.0).abs();
            anyhow::ensure!(jump < tol, "{name} jumps by {jump:e} at {p} Pa");
        }
    }
    Ok(())
}

#[test]
fn test_steam_saturation_brackets_the_liquid_and_vapour_regions() -> anyhow::Result<()> {
    for t in [280.0, 373.15, 500.0, 620.0] {
        let p_sat =
            steam::saturation_pressure(ThermodynamicTemperature::new::<kelvin>(t))?.get::<pascal>();
        let liquid = at(p_sat * (1.0 + 1e-9), t)?;
        let vapour = at(p_sat * (1.0 - 1e-9), t)?;
        anyhow::ensure!(
            liquid.region == Region::CompressedLiquid,
            "{:?}",
            liquid.region
        );
        anyhow::ensure!(vapour.region == Region::Vapour, "{:?}", vapour.region);
        // Equal Gibbs energy g = h − Ts of the coexisting phases.
        let gibbs = |x: &steam::SteamProperties| {
            x.enthalpy.get::<joule_per_kilogram>()
                - t * x.entropy.get::<joule_per_kilogram_kelvin>()
        };
        let (g_l, g_v) = (gibbs(&liquid), gibbs(&vapour));
        let latent = vapour.enthalpy.get::<joule_per_kilogram>()
            - liquid.enthalpy.get::<joule_per_kilogram>();
        anyhow::ensure!(
            (g_l - g_v).abs() < 1e-5 * latent,
            "{t} K: g' = {g_l}, g'' = {g_v}"
        );
    }
    Ok(())
}
